@Allow.WarmPool.local_preserves_safety : ∀ {now : Nat} {event : Allow.WarmPool.Event}
  {s peer t : Allow.WarmPool.Worker},
  Allow.WarmPool.WorkerSafe s → Allow.WarmPool.LocalStep now event s peer t → Allow.WarmPool.WorkerSafe t

@Allow.WarmPool.local_preserves_standby_bound : ∀ {now : Nat} {event : Allow.WarmPool.Event}
  {s peer t : Allow.WarmPool.Worker},
  LE.le.{0} (HAdd.hAdd.{0, 0, 0} (Allow.WarmPool.unassigned s) (Allow.WarmPool.unassigned peer)) 1 →
    Allow.WarmPool.LocalStep now event s peer t →
      LE.le.{0} (HAdd.hAdd.{0, 0, 0} (Allow.WarmPool.unassigned t) (Allow.WarmPool.unassigned peer)) 1

@Allow.WarmPool.local_preserves_active_bound : ∀ {now : Nat} {event : Allow.WarmPool.Event}
  {s peer t : Allow.WarmPool.Worker},
  Allow.WarmPool.WorkerSafe s →
    LE.le.{0} (HAdd.hAdd.{0, 0, 0} (Allow.WarmPool.active s) (Allow.WarmPool.active peer)) 1 →
      Allow.WarmPool.LocalStep now event s peer t →
        LE.le.{0} (HAdd.hAdd.{0, 0, 0} (Allow.WarmPool.active t) (Allow.WarmPool.active peer)) 1

@Allow.WarmPool.at_most_one_unassigned : ∀ {p : Allow.WarmPool.Pool},
  Allow.WarmPool.Reachable p →
    LE.le.{0} (HAdd.hAdd.{0, 0, 0} (Allow.WarmPool.unassigned p.first) (Allow.WarmPool.unassigned p.second)) 1

@Allow.WarmPool.at_most_one_assigned : ∀ {p : Allow.WarmPool.Pool},
  Allow.WarmPool.Reachable p →
    LE.le.{0} (HAdd.hAdd.{0, 0, 0} (Allow.WarmPool.active p.first) (Allow.WarmPool.active p.second)) 1

@Allow.WarmPool.no_busy_to_ready : ∀ {now : Nat} {event : Allow.WarmPool.Event} {s peer t : Allow.WarmPool.Worker},
  Allow.WarmPool.LocalStep now event s peer t →
    Eq.{1} s.phase Allow.WarmPool.Phase.busy → Ne.{1} t.phase Allow.WarmPool.Phase.ready

@Allow.WarmPool.release_requires_cleanup : ∀ {now : Nat} {s peer t : Allow.WarmPool.Worker},
  Allow.WarmPool.LocalStep now Allow.WarmPool.Event.release s peer t →
    Eq.{1} s.phase Allow.WarmPool.Phase.reaped ∧ Eq.{1} s.cleanup true

@Allow.WarmPool.owned_release_refines_step : ∀ {now : Nat} {s peer t : Allow.WarmPool.Worker}
  {identity : Allow.WarmPool.Owner},
  Eq.{1} (Allow.WarmPool.releaseOwned s identity) (some.{0} t) →
    Allow.WarmPool.LocalStep now Allow.WarmPool.Event.release s peer t

@Allow.WarmPool.poison_sticky_same_generation : ∀ {now : Nat} {event : Allow.WarmPool.Event}
  {s peer t : Allow.WarmPool.Worker},
  Allow.WarmPool.LocalStep now event s peer t →
    Eq.{1} s.poisoned true → Eq.{1} t.owner.generation s.owner.generation → Eq.{1} t.poisoned true

@Allow.WarmPool.attempted_sticky_same_generation : ∀ {now : Nat} {event : Allow.WarmPool.Event}
  {s peer t : Allow.WarmPool.Worker},
  Allow.WarmPool.LocalStep now event s peer t →
    Eq.{1} s.attempted true → Eq.{1} t.owner.generation s.owner.generation → Eq.{1} t.attempted true

@Allow.WarmPool.consumption_monotone_same_generation : ∀ {now : Nat} {event : Allow.WarmPool.Event}
  {s peer t : Allow.WarmPool.Worker},
  Allow.WarmPool.LocalStep now event s peer t →
    Eq.{1} t.owner.generation s.owner.generation → LE.le.{0} s.consumed t.consumed

@Allow.WarmPool.handoff_sets_clean_context : ∀ {now : Nat} {s peer t : Allow.WarmPool.Worker},
  Allow.WarmPool.LocalStep now Allow.WarmPool.Event.handoff s peer t →
    Eq.{1} t.contextClean true ∧ LT.lt.{0} now t.requestDeadline

@Allow.WarmPool.offline_step_preserves_delivery : ∀ {p q : Allow.WarmPool.Pool},
  Allow.WarmPool.Step p q →
    Eq.{1} p.online false → Eq.{1} q.first.delivered p.first.delivered ∧ Eq.{1} q.second.delivered p.second.delivered
